beginning.embedded_functions:
// Buffer to store original PDU length
static char original_pdu_length[5];  // 4 bytes + null terminator

static void em_invalid_max_pdu_length(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {

    // Get original PDU length (attribute 2)
    int ret = get_dicom_attribute(701, 8, original_pdu_length);
    if (ret < 0) {
        log_info("Failed to get PDU length");
        forward_packet();
        return;
    }

    //uint32_t new_length = 0x02000000;  // Set an excessive PDU length (32MB) in hex
    uint32_t new_length = 0; // Set a zero length

    // Replace with excessive length
    replace_dicom_attribute(701, 8, &new_length, 0);
    log_info("Modified PDU Length to: %u bytes", new_length);

    forward_packet();
}
